1	// daily 子命令:按 UTC 自然日核查能耗的只读日报。
2	//
3	// 估算口径:
4	// - 区间由每个设备完整已存时序的相邻读数构成,两端读数即使在查询范围外
5	//   也参与;范围内没有读数但被区间覆盖时仍得到结果。
6	// - 非下降区间把累计值之差按持续时间均匀分摊:以千分之一 kWh 为单位,
7	//   从区间起点累计到任一切点 t 的比例量为 floor(diff*(t-start)/duration),
8	//   片段消耗为终点与起点累计量之差。切点为查询边界与 UTC 日界线,因此
9	//   完整区间的分摊总量等于原差值,同一区间拆开查询再相加结果一致。
10	// - 中间乘积与多区间汇总使用 BigInt,超过 Number 安全整数范围仍精确。
11	// - 下降区间不分摊消耗,记为异常覆盖;其后的区间仍从下降后的读数计算。
12	// - 首条读数之前、末条之后及孤立读数时段为未知,不外推。
13	
14	import { loadStore, StoreError, dataFilePath, type Reading } from './store.ts';
15	import { formatIsoUtc } from './time.ts';
16	import { formatKwh } from './value.ts';
17	
18	export interface DailyFilter {
19	  devices: string[];
20	  /** 查询起点(含),epoch 秒。 */
21	  from: number;
22	  /** 查询终点(不含),epoch 秒。 */
23	  to: number;
24	}
25	
26	export const DAY_SECONDS = 86400;
27	
28	function err(message: string): void {
29	  console.error(`meterwatch: ${message}`);
30	}
31	
32	export interface DayStats {
33	  /** 有效(非下降区间)覆盖秒数。 */
34	  valid: number;
35	  /** 异常(下降区间)覆盖秒数。 */
36	  anomaly: number;
37	  /** 未知(无区间覆盖)秒数。 */
38	  unknown: number;
39	  /** 该天分摊消耗,毫千瓦时;仅 valid > 0 时有意义。 */
40	  consumption: bigint;
41	}
42	
43	/** 计算 [segStart, segEnd) 一天的统计;区间取自完整时序。 */
44	export function computeDay(series: Reading[], segStart: number, segEnd: number): DayStats {
45	  let valid = 0;
46	  let anomaly = 0;
47	  let consumption = 0n;
48	  for (let i = 1; i < series.length; i++) {
49	    const a = series[i - 1];
50	    const b = series[i];
51	    const lo = Math.max(a.ts, segStart);
52	    const hi = Math.min(b.ts, segEnd);
53	    if (lo >= hi) continue;
54	    const diff = b.milli - a.milli;
55	    if (diff < 0n) {
56	      anomaly += hi - lo;
57	    } else {
58	      valid += hi - lo;
59	      const duration = BigInt(b.ts - a.ts);
60	      const total = diff;
61	      // 从区间起点累计到 t 的比例量(向下取整);BigInt 除法向零截断,
62	      // 被除数非负,等价于向下取整。
63	      const cumulative = (t: number): bigint => (total * BigInt(t - a.ts)) / duration;
64	      consumption += cumulative(hi) - cumulative(lo);
65	    }
66	  }
67	  const unknown = segEnd - segStart - valid - anomaly;
68	  return { valid, anomaly, unknown, consumption };
69	}
70	
71	/**
72	 * 输出按 UTC 自然日划分的能耗日报。只读,不修改数据。
73	 * 同设备同一实际时刻存在多条存储记录时报错并返回 1。
74	 * 返回进程退出码。
75	 */
76	export function cmdDaily(filter: DailyFilter): number {
77	  const storePath = dataFilePath();
78	  let all: Reading[];
79	  try {
80	    all = loadStore(storePath);
81	  } catch (e) {
82	    if (e instanceof StoreError) {
83	      err(e.message);
84	      return 1;
85	    }
86	    throw e;
87	  }
88	
89	  const byDevice = new Map<string, Reading[]>();
90	  for (const r of all) {
91	    const list = byDevice.get(r.device);
92	    if (list) list.push(r);
93	    else byDevice.set(r.device, [r]);
94	  }
95	  for (const [device, list] of byDevice) {
96	    list.sort((a, b) => a.ts - b.ts);
97	    for (let i = 1; i < list.length; i++) {
98	      if (list[i].ts === list[i - 1].ts) {
99	        err(
100	          `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`,
101	        );
102	        return 1;
103	      }
104	    }
105	  }
106	
107	  const wanted =
108	    filter.devices.length > 0 ? [...new Set(filter.devices)] : [...byDevice.keys()];
109	  wanted.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
110	
111	  let printed = false;
112	  for (const device of wanted) {
113	    const series = byDevice.get(device);
114	    if (!series) continue;
115	    printed = true;
116	
117	    console.log(`device: ${device}`);
118	    let total = 0n;
119	    let computedDays = 0;
120	    let days = 0;
121	    let incomplete = false;
122	    for (let dayStart = Math.floor(filter.from / DAY_SECONDS) * DAY_SECONDS;
123	      dayStart < filter.to;
124	      dayStart += DAY_SECONDS) {
125	      const segStart = Math.max(dayStart, filter.from);
126	      const segEnd = Math.min(dayStart + DAY_SECONDS, filter.to);
127	      const stats = computeDay(series, segStart, segEnd);
128	      days++;
129	
130	      const date = formatIsoUtc(dayStart).slice(0, 10);
