1	// 每日能耗阈值告警:规则管理、评估、告警历史查询与确认。
2	//
3	// 规则分两类,由 targetType 区分:
4	// - device 规则绑定一个已有设备;
5	// - group 规则绑定一个已有分组标识(不冻结创建时成员,每天按当时生效的成员
6	//   版本计算,允许日内切换)。
7	// 设备与分组即使同名也是不同目标;规则标识在两类规则间统一唯一(去首尾空白、
8	// 区分大小写)。阈值为非负、最多三位小数的 kWh,绑定目标与阈值创建后固定。
9	// 相同标识、同目标类型、同目标标识及等价阈值重试成功且不重复创建,异参报冲突。
10	//
11	// - 评估针对连续完整 UTC 日期(起日含、止日不含)。设备规则复用 daily 的完整
12	//   时序、均匀分摊与累计比例向下取整口径;分组规则复用 group daily 的联合覆盖
13	//   口径:每天按当时生效的成员版本切分时段(允许日内切换),任一成员下降为异常,
14	//   否则任一成员未知为未知,首个版本生效前为未知;成员切换不重置各设备原读数
15	//   区间的分摊起点。仅全天有效覆盖的日期可判定,消耗严格大于阈值才超限,等于
16	//   阈值视为正常;有未知或下降覆盖时不可判定,不触发也不恢复;零增长是有效数据。
17	// - 每条规则的每个日期独立跟踪:首次判定超限创建全局唯一标识的未确认告警,
18	//   重复超限保留原标识且不新增事件;后续完整评估正常才记录恢复;恢复后再
19	//   超限创建新的未确认告警,旧记录保留,原确认不转移给新告警。
20	// - 确认按告警标识,已恢复告警也可确认;重复确认成功且不重复记事;确认不
21	//   改变超限或恢复状态。
22	// - 规则与历史存于数据目录的 alerts.json(与 readings.json、groups.json 相互
23	//   独立,导入与补录成员版本都不会自动评估)。创建、评估、确认都先在内存完成
24	//   全部计算再一次性原子写入,任何失败不留下部分状态;损坏或不可读存储明确
25	//   报错,绝不当作空库。旧版仅含 device 字段的规则无需手工转换即可继续使用。
26	
27	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
28	import { dirname } from 'node:path';
29	import {
30	  alertFilePath,
31	  dataFilePath,
32	  groupFilePath,
33	  loadStore,
34	  parseStoredMilli,
35	  StoreError,
36	  type Reading,
37	} from './store.ts';
38	import { computeDay, DAY_SECONDS, type DayStats } from './report.ts';
39	import { computeGroupSegment, loadCheckedSeriesByDevice, loadGroups, type Group } from './groups.ts';
40	import { formatIsoUtc, parseIso8601 } from './time.ts';
41	import { formatKwh } from './value.ts';
42	
43	export type RuleTargetType = 'device' | 'group';
44	
45	export interface AlertRule {
46	  /** 规则标识(非空、唯一,已去首尾空白,设备与分组规则间统一唯一)。 */
47	  id: string;
48	  /** 目标类型:设备或分组。 */
49	  targetType: RuleTargetType;
50	  /** 绑定的设备或分组标识(已去首尾空白,区分大小写),创建后固定。 */
51	  targetId: string;
52	  /** 阈值,毫千瓦时 BigInt,创建后固定。 */
53	  thresholdMilli: bigint;
54	}
55	
56	export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';
57	
58	export interface AlertEvent {
59	  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
60	  seq: number;
61	  type: AlertEventType;
62	  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
63	  consumptionMilli?: string;
64	}
65	
66	export interface AlertRecord {
67	  /** 告警标识,全局唯一(设备与分组规则共用编号空间)。 */
68	  id: string;
69	  ruleId: string;
70	  /** UTC 日期,YYYY-MM-DD。 */
71	  date: string;
72	  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
73	  status: 'triggered' | 'recovered';
74	  acknowledged: boolean;
75	  events: AlertEvent[];
76	}
77	
78	interface AlertState {
79	  nextAlertNum: number;
80	  nextEventSeq: number;
81	  rules: AlertRule[];
82	  alerts: AlertRecord[];
83	}
84	
85	function err(message: string): void {
86	  console.error(`meterwatch: ${message}`);
87	}
88	
89	function emptyState(): AlertState {
90	  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
91	}
92	
93	/** 目标在输出中的显示形式,如 device=meter-1 / group=floor-1。 */
94	function targetLabel(rule: Pick<AlertRule, 'targetType' | 'targetId'>): string {
95	  return `${rule.targetType}=${rule.targetId}`;
96	}
97	
98	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
99	function loadAlertState(path: string): AlertState {
100	  let text: string;
101	  try {
102	    text = readFileSync(path, 'utf8');
103	  } catch (e) {
104	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
105	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
106	  }
107	  let data: unknown;
108	  try {
109	    data = JSON.parse(text);
110	  } catch {
111	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
112	  }
113	  const bad = (what: string): StoreError =>
114	    new StoreError(`storage file ${path} is corrupted (${what})`);
115	  const o = data as Record<string, unknown>;
116	  if (o === null || typeof o !== 'object') throw bad('not an object');
117	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
118	    throw bad('invalid nextAlertNum');
119	  }
120	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
121	    throw bad('invalid nextEventSeq');
122	  }
123	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
124	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
125	
126	  const ruleIds = new Set<string>();
127	  const rules: AlertRule[] = [];
128	  for (const r of o.rules as Array<Record<string, unknown>>) {
129	    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
130	    // 按损坏数据拒绝,不猜测原值。
131	    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
132	    if (
133	      r === null ||
134	      typeof r !== 'object' ||
135	      typeof r.id !== 'string' ||
136	      r.id.length === 0 ||
137	      thresholdMilli === null
138	    ) {
139	      throw bad('invalid rule entry');
140	    }
141	    // 目标类型:新版字段 targetType/targetId;旧版只有 device 字段,按 device 规则
142	    // 读入,已有设备规则无需手工转换即可继续使用。
143	    let targetType: RuleTargetType;
144	    let targetId: string;
145	    if (r.targetType === undefined) {
146	      if (typeof r.device !== 'string' || r.device.length === 0) throw bad('invalid rule entry');
147	      targetType = 'device';
148	      targetId = r.device;
149	    } else {
150	      if (r.targetType !== 'device' && r.targetType !== 'group') {
151	        throw bad(`invalid targetType in rule '${r.id}'`);
152	      }
153	      if (typeof r.targetId !== 'string' || r.targetId.length === 0) {
154	        throw bad(`invalid targetId in rule '${r.id}'`);
155	      }
156	      targetType = r.targetType;
157	      targetId = r.targetId;
158	    }
159	    if (ruleIds.has(r.id)) throw bad(`duplicate rule id '${r.id}'`);
160	    ruleIds.add(r.id);
161	    rules.push({ id: r.id, targetType, targetId, thresholdMilli: thresholdMilli as bigint });
162	  }
163	
164	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
165	  const alertIds = new Set<string>();
166	  for (const a of o.alerts as Array<Record<string, unknown>>) {
167	    const ok =
168	      a !== null &&
169	      typeof a === 'object' &&
170	      typeof a.id === 'string' &&
171	      a.id.length > 0 &&
172	      typeof a.ruleId === 'string' &&
173	      ruleIds.has(a.ruleId) &&
174	      typeof a.date === 'string' &&
175	      DATE_RE.test(a.date) &&
176	      (a.status === 'triggered' || a.status === 'recovered') &&
177	      typeof a.acknowledged === 'boolean' &&
178	      Array.isArray(a.events) &&
179	      (a.events as unknown[]).length > 0;
180	    if (!ok) throw bad('invalid alert entry');
181	    if (alertIds.has(a.id)) throw bad(`duplicate alert id '${a.id}'`);
182	    alertIds.add(a.id);
183	    const seqs = new Set<number>();
184	    for (const e of a.events as Array<Record<string, unknown>>) {
185	      const eok =
186	        e !== null &&
187	        typeof e === 'object' &&
188	        Number.isSafeInteger(e.seq) &&
189	        (e.seq as number) >= 1 &&
190	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
191	        (e.consumptionMilli === undefined ||
192	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
193	      if (!eok) throw bad('invalid alert event');
194	      if (seqs.has(e.seq as number)) throw bad(`duplicate event seq in alert '${a.id}'`);
195	      seqs.add(e.seq as number);
196	    }
197	  }
198	  return {
199	    nextAlertNum: o.nextAlertNum as number,
200	    nextEventSeq: o.nextEventSeq as number,
201	    rules,
202	    alerts: o.alerts as unknown as AlertRecord[],
203	  };
204	}
205	
206	/**
207	 * 原子写入告警存储;失败抛错,原有数据保持不变。
208	 * 告警写入不触碰读数与成员版本文件。
209	 */
210	function saveAlertState(path: string, state: AlertState): void {
211	  mkdirSync(dirname(path), { recursive: true });
212	  const tmp = `${path}.tmp-${process.pid}`;
213	  const body =
214	    JSON.stringify(
215	      {
216	        version: 2,
217	        ...state,
218	        rules: state.rules.map((r) => ({
219	          id: r.id,
220	          targetType: r.targetType,
221	          targetId: r.targetId,
222	          thresholdMilli: r.thresholdMilli.toString(),
223	        })),
224	      },
225	      null,
226	      2,
227	    ) + '\n';
228	  try {
229	    writeFileSync(tmp, body, 'utf8');
230	    renameSync(tmp, path);
231	  } catch (e) {
232	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
233	  }
234	}
235	
236	/**
237	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
238	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
239	 */
240	function deviceSeries(device: string): Reading[] {
241	  const all = loadStore(dataFilePath());
242	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
243	  for (let i = 1; i < series.length; i++) {
244	    if (series[i].ts === series[i - 1].ts) {
245	      throw new StoreError(
246	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
247	      );
248	    }
249	  }
250	  return series;
251	}
252	
253	/**
254	 * 分组规则的评估环境:绑定分组与全库设备时序。
255	 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
256	 */
257	interface GroupEnv {
258	  kind: 'group';
259	  group: Group;
260	  byDevice: Map<string, Reading[]>;
261	}
262	
263	interface DeviceEnv {
264	  kind: 'device';
265	  series: Reading[];
266	}
267	
268	type RuleEnv = DeviceEnv | GroupEnv;
269	
270	/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
271	function prepareEnv(rule: AlertRule): RuleEnv {
272	  if (rule.targetType === 'device') {
273	    return { kind: 'device', series: deviceSeries(rule.targetId) };
274	  }
275	  const groups = loadGroups(groupFilePath());
276	  const group = groups.find((g) => g.id === rule.targetId);
277	  if (!group) {
278	    throw new StoreError(
279	      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
280	    );
281	  }
282	  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
283	  return { kind: 'group', group, byDevice };
284	}
285	
286	/** 不可判定原因(未知/异常覆盖秒数)。 */
287	function undecidableReason(stats: Pick<DayStats, 'unknown' | 'anomaly'>): string {
288	  return `undecidable (unknown=${stats.unknown}s anomaly=${stats.anomaly}s)`;
289	}
290	
291	/**
292	 * 计算规则在完整 UTC 日 [dayStart, dayStart+86400) 上的统计。
293	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径。
294	 */
295	function computeRuleDay(rule: AlertRule, env: RuleEnv, dayStart: number): DayStats {
296	  const dayEnd = dayStart + DAY_SECONDS;
297	  if (env.kind === 'device') {
298	    return computeDay(env.series, dayStart, dayEnd);
299	  }
300	  const stats = computeGroupSegment(env.group.versions, env.byDevice, dayStart, dayEnd);
301	  return {
302	    valid: stats.valid,
303	    anomaly: stats.anomaly,
304	    unknown: stats.unknown,
305	    consumption: stats.consumption,
306	  };
307	}
308	
309	/**
310	 * 创建规则。相同标识、同目标类型、同目标标识及等价阈值重试成功且不重复创建;
311	 * 任一不同即报冲突。设备必须已有存储读数;分组必须已配置。返回进程退出码。
312	 */
313	export function cmdRuleCreate(opts: {
314	  id: string;
315	  targetType: RuleTargetType;
316	  targetId: string;
317	  thresholdMilli: bigint;
318	}): number {
319	  const statePath = alertFilePath();
320	  let state: AlertState;
321	  try {
322	    state = loadAlertState(statePath);
323	  } catch (e) {
324	    if (e instanceof StoreError) {
325	      err(e.message);
326	      return 1;
327	    }
328	    throw e;
329	  }
330	
331	  const got = `${opts.targetType}=${opts.targetId}`;
332	  const existing = state.rules.find((r) => r.id === opts.id);
333	  if (existing) {
334	    if (
335	      existing.targetType === opts.targetType &&
336	      existing.targetId === opts.targetId &&
337	      existing.thresholdMilli === opts.thresholdMilli
338	    ) {
339	      console.log(
340	        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
341	          `threshold=${formatKwh(existing.thresholdMilli)} kWh); unchanged`,
342	      );
343	      return 0;
344	    }
345	    err(
346	      `rule '${opts.id}' already exists with different parameters ` +
347	        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh, ` +
348	        `got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh); conflict`,
349	    );
350	    return 1;
351	  }
352	
353	  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
354	  try {
355	    if (opts.targetType === 'device') {
356	      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
357	      if (!devices.has(opts.targetId)) {
358	        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
359	        return 1;
360	      }
361	    } else {
362	      const groups = loadGroups(groupFilePath());
363	      if (!groups.some((g) => g.id === opts.targetId)) {
364	        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
365	        return 1;
366	      }
367	    }
368	  } catch (e) {
369	    if (e instanceof StoreError) {
370	      err(e.message);
371	      return 1;
372	    }
373	    throw e;
374	  }
375	
376	  state.rules.push({
377	    id: opts.id,
378	    targetType: opts.targetType,
379	    targetId: opts.targetId,
380	    thresholdMilli: opts.thresholdMilli,
381	  });
382	  try {
383	    saveAlertState(statePath, state);
384	  } catch (e) {
385	    if (e instanceof StoreError) {
386	      err(e.message);
387	      return 1;
388	    }
389	    throw e;
390	  }
391	  console.log(
392	    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh`,
393	  );
394	  return 0;
395	}
396	
397	/** 列出全部规则(含目标类型)。只读。返回进程退出码。 */
398	export function cmdRuleList(): number {
399	  let state: AlertState;
400	  try {
401	    state = loadAlertState(alertFilePath());
402	  } catch (e) {
403	    if (e instanceof StoreError) {
404	      err(e.message);
405	      return 1;
406	    }
407	    throw e;
408	  }
409	  if (state.rules.length === 0) {
410	    console.log('no rules defined');
411	    return 0;
412	  }
413	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
414	  for (const r of rules) {
415	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
416	    console.log(
417	      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  open alerts=${open}`,
418	    );
419	  }
420	  return 0;
421	}
422	
423	/**
424	 * 评估规则在连续完整 UTC 日期范围 [from, to) 上的超限情况。
425	 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途任一存储
426	 * 或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
427	 */
428	export function cmdEvaluate(opts: { ruleId: string; from: number; to: number }): number {
429	  const statePath = alertFilePath();
430	  let state: AlertState;
431	  let rule: AlertRule;
432	  let env: RuleEnv;
433	  try {
434	    state = loadAlertState(statePath);
435	    const found = state.rules.find((r) => r.id === opts.ruleId);
436	    if (!found) {
437	      err(`unknown rule '${opts.ruleId}'`);
438	      return 1;
439	    }
440	    rule = found;
441	    env = prepareEnv(rule);
442	  } catch (e) {
443	    if (e instanceof StoreError) {
444	      err(e.message);
445	      return 1;
446	    }
447	    throw e;
448	  }
449	
450	  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
451	  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
452	  const alertIds = new Set(state.alerts.map((a) => a.id));
453	
454	  const threshold = rule.thresholdMilli;
455	  const lines: string[] = [];
456	  for (let dayStart = opts.from; dayStart < opts.to; dayStart += DAY_SECONDS) {
457	    const date = formatIsoUtc(dayStart).slice(0, 10);
458	    const stats = computeRuleDay(rule, env, dayStart);
459	    if (stats.unknown > 0 || stats.anomaly > 0) {
460	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
461	      lines.push(`  ${date}  ${undecidableReason(stats)}  no alert action`);
462	      continue;
463	    }
464	    const exceeded = stats.consumption > threshold;
465	    const cmp =
466	      `consumption=${formatKwh(stats.consumption)} kWh ` +
467	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
468	    const open = state.alerts.find(
469	      (a) => a.ruleId === rule.id && a.date === date && a.status === 'triggered',
470	    );
471	    if (exceeded) {
472	      if (open) {
473	        // 重复超限:保留原标识,不新增事件。
474	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered`);
475	      } else {
476	        const id = `alert-${state.nextAlertNum++}`;
477	        if (alertIds.has(id)) {
478	          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
479	          return 1;
480	        }
481	        alertIds.add(id);
482	        state.alerts.push({
483	          id,
484	          ruleId: rule.id,
485	          date,
486	          status: 'triggered',
487	          acknowledged: false,
488	          events: [
489	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
490	          ],
491	        });
492	        lines.push(`  ${date}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)`);
493	      }
494	    } else {
495	      if (open) {
496	        open.status = 'recovered';
497	        open.events.push({
498	          seq: state.nextEventSeq++,
499	          type: 'recovered',
500	          consumptionMilli: stats.consumption.toString(),
501	        });
502	        lines.push(`  ${date}  ${cmp}  NORMAL  alert ${open.id} recovered`);
503	      } else {
504	        lines.push(`  ${date}  ${cmp}  NORMAL  no alert`);
505	      }
506	    }
507	  }
508	
509	  try {
510	    saveAlertState(statePath, state);
511	  } catch (e) {
512	    if (e instanceof StoreError) {
513	      err(e.message);
514	      return 1;
515	    }
516	    throw e;
517	  }
518	
519	  console.log(
520	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
521	  );
522	  for (const line of lines) console.log(line);
523	  return 0;
524	}
525	
526	/**
527	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
528	 * 给定日期范围时逐日展示当前计算的消耗或不可判定原因及各次告警;省略范围时
529	 * 展示有告警记录的全部日期。触发/恢复事件中的消耗为评估当时记录,不随后续
530	 * 数据变化改写。返回进程退出码。
531	 */
532	export function cmdAlerts(opts: { ruleId: string; from?: number; to?: number }): number {
533	  let state: AlertState;
534	  let rule: AlertRule;
535	  let env: RuleEnv;
536	  try {
537	    state = loadAlertState(alertFilePath());
538	    const found = state.rules.find((r) => r.id === opts.ruleId);
539	    if (!found) {
540	      err(`unknown rule '${opts.ruleId}'`);
541	      return 1;
542	    }
543	    rule = found;
544	    env = prepareEnv(rule);
545	  } catch (e) {
546	    if (e instanceof StoreError) {
547	      err(e.message);
548	      return 1;
549	    }
550	    throw e;
551	  }
552	
553	  let dayStarts: number[];
554	  if (opts.from !== undefined && opts.to !== undefined) {
555	    dayStarts = [];
556	    for (let d = opts.from; d < opts.to; d += DAY_SECONDS) dayStarts.push(d);
557	  } else {
558	    const dates = [
559	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
560	    ].sort();
561	    dayStarts = dates.map((d) => parseIso8601(`${d}T00:00:00Z`) as number);
562	  }
563	
564	  console.log(
565	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
566	  );
567	  if (dayStarts.length === 0) {
568	    console.log(`  no alerts recorded for rule '${rule.id}'`);
569	    return 0;
570	  }
571	
572	  const threshold = rule.thresholdMilli;
573	  for (const dayStart of dayStarts) {
574	    const date = formatIsoUtc(dayStart).slice(0, 10);
575	    const stats = computeRuleDay(rule, env, dayStart);
576	    if (stats.unknown > 0 || stats.anomaly > 0) {
577	      console.log(`  ${date}  ${undecidableReason(stats)}`);
578	    } else {
579	      const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
580	      console.log(
581	        `  ${date}  consumption=${formatKwh(stats.consumption)} kWh ` +
582	          `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)`,
583	      );
584	    }
585	    const alerts = state.alerts
586	      .filter((a) => a.ruleId === rule.id && a.date === date)
587	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
588	    if (alerts.length === 0) {
589	      console.log('    no alerts');
590	      continue;
591	    }
592	    for (const a of alerts) {
593	      console.log(
594	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
595	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
596	      );
597	      const events = a.events
598	        .map((e) => {
599	          const consumption =
600	            e.consumptionMilli !== undefined
601	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
602	              : '';
603	          return `#${e.seq} ${e.type}${consumption}`;
604	        })
605	        .join(', ');
606	      console.log(`      events: ${events}`);
607	    }
608	  }
609	  return 0;
610	}
611	
612	/**
613	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
614	 * 确认不改变超限或恢复状态。返回进程退出码。
615	 */
616	export function cmdAck(alertId: string): number {
617	  const statePath = alertFilePath();
618	  let state: AlertState;
619	  try {
620	    state = loadAlertState(statePath);
621	  } catch (e) {
622	    if (e instanceof StoreError) {
623	      err(e.message);
624	      return 1;
625	    }
626	    throw e;
627	  }
628	  const alert = state.alerts.find((a) => a.id === alertId);
629	  if (!alert) {
630	    err(`unknown alert '${alertId}'`);
631	    return 1;
632	  }
633	  if (alert.acknowledged) {
634	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
635	    return 0;
636	  }
637	  alert.acknowledged = true;
638	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
639	  try {
640	    saveAlertState(statePath, state);
641	  } catch (e) {
642	    if (e instanceof StoreError) {
643	      err(e.message);
644	      return 1;
645	    }
646	    throw e;
647	  }
648	  const rule = state.rules.find((r) => r.id === alert.ruleId);
649	  const target = rule ? ` ${targetLabel(rule)}` : '';
650	  console.log(
651	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
652	  );
653	  return 0;
654	}
